<script setup lang="ts">
import type { Application, Finding, GovernanceLink, GovernanceProject, GovernanceResponsibility, UserOption } from '#/api/agent-tools/code-quality-governance';
import { computed, onMounted, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { ElButton, ElCard, ElDialog, ElDescriptions, ElDescriptionsItem, ElEmpty, ElForm, ElFormItem, ElInput, ElMessage, ElMessageBox, ElOption, ElSelect, ElStatistic, ElTable, ElTableColumn, ElTabs, ElTabPane, ElTag, ElUpload } from 'element-plus';
import { createApplicationApi, createLinkApi, createProjectApi, createResponsibilityApi, deleteLinkApi, deleteProjectApi, deleteResponsibilityApi, getFindingApi, getSummaryApi, listApplicationsApi, listFindingsApi, listLinksApi, listProjectsApi, listResponsibilitiesApi, listUsersApi, rejectApplicationApi, approveApplicationApi, updateProjectApi, updateResponsibilityApi, uploadReportApi } from '#/api/agent-tools/code-quality-governance';
import AgentToolsPageShell from '../components/agent-tools-page-shell.vue';
import { useZqTable } from '#/components/zq-table';

defineOptions({ name: 'CodeQualityGovernance' });
type Section = 'dashboard' | 'config' | 'findings' | 'audit';
const section = ref<Section>('dashboard');
const projects = ref<GovernanceProject[]>([]); const responsibilities = ref<GovernanceResponsibility[]>([]); const links = ref<GovernanceLink[]>([]); const users = ref<UserOption[]>([]); const summary = ref<any>({ total: 0, normal: 0, pending: 0, shielded: 0, pending_applications: 0, severity: {} });
const filters = ref({ project_id: '', responsibility_id: '', severity: '', shield_status: '', keyword: '' });
const configTab = ref<'projects' | 'responsibilities' | 'links' | 'upload'>('projects'); const auditTab = ref<'my_audit' | 'my_apply'>('my_audit'); const selected = ref<Finding[]>([]);
const dialog = ref<'project' | 'responsibility' | 'link' | 'upload' | 'apply' | 'detail' | 'audit' | ''>(''); const editingId = ref(''); const detail = ref<Finding | null>(null); const auditRow = ref<Application | null>(null); const file = ref<File | null>(null);
const projectForm = ref({ name: '', code: '', repository: '', branch: 'master', description: '', is_active: true }); const responsibilityForm = ref({ name: '', code: '', owner_id: '', approver_ids: [] as string[], description: '', is_active: true }); const linkForm = ref({ project_id: '', responsibility_id: '', remark: '', is_active: true }); const uploadForm = ref({ project_id: '', responsibility_id: '', tool_name: '' }); const applyForm = ref({ approver_id: '', reason: '' }); const auditComment = ref('');
const applyApprovers = computed(() => { const name = selected.value[0]?.responsibility_name; return responsibilities.value.find((item) => item.name === name)?.approvers || []; });
function formatApprovers(items: UserOption[]) { return items.map((item) => item.name).join('、') || '-'; }
const dialogVisible = computed({ get: () => Boolean(dialog.value), set: (value: boolean) => { if (!value) dialog.value = ''; } });
const pageTitle = computed(() => ({ dashboard: '治理看板', config: '项目与责任田', findings: '问题明细', audit: '屏蔽审核' })[section.value]);
async function loadBase() { const [projectPage, responsibilityPage, linkPage, userData] = await Promise.all([listProjectsApi(), listResponsibilitiesApi(), listLinksApi(), listUsersApi()]); projects.value = projectPage.items; responsibilities.value = responsibilityPage.items; links.value = linkPage.items; users.value = userData; }
const [FindingGrid, findingGridApi] = useZqTable<Finding>({ gridOptions: { border: true, stripe: true, columns: [{ type: 'selection', width: 48, fixed: 'left' }, { key: 'severity', dataKey: 'severity', title: '级别', width: 100, slots: { default: 'cell-severity' } }, { key: 'project_name', dataKey: 'project_name', title: '项目', width: 150 }, { key: 'responsibility_name', dataKey: 'responsibility_name', title: '责任田', width: 140 }, { key: 'rule_id', dataKey: 'rule_id', title: '规则', width: 170 }, { key: 'latest_file_path', dataKey: 'latest_file_path', title: '文件', minWidth: 220 }, { key: 'latest_line', dataKey: 'latest_line', title: '行', width: 70 }, { key: 'latest_message', dataKey: 'latest_message', title: '问题描述', minWidth: 280 }, { key: 'shield_status', dataKey: 'shield_status', title: '状态', width: 120 }, { key: 'actions', dataKey: 'actions', title: '操作', width: 80, slots: { default: 'cell-actions' } }] as any, proxyConfig: { autoLoad: false, ajax: { query: async ({ page }) => listFindingsApi({ ...filters.value, page: page.currentPage, pageSize: page.pageSize }) } }, pagerConfig: { enabled: true, pageSize: 20, pageSizes: [10, 20, 50, 100] }, toolbarConfig: { custom: true, refresh: true, zoom: true } } });
const [ApplicationGrid, applicationGridApi] = useZqTable<Application>({ gridOptions: { border: true, stripe: true, columns: [{ key: 'project_name', dataKey: 'project_name', title: '项目', width: 150 }, { key: 'responsibility_name', dataKey: 'responsibility_name', title: '责任田', width: 140 }, { key: 'severity', dataKey: 'severity', title: '级别', width: 90 }, { key: 'file_path', dataKey: 'file_path', title: '文件', minWidth: 220 }, { key: 'applicant', dataKey: 'applicant', title: '申请人', width: 100, formatter: (row: Application) => row.applicant?.name || '-' }, { key: 'reason', dataKey: 'reason', title: '申请理由', minWidth: 260 }, { key: 'status', dataKey: 'status', title: '状态', width: 100 }, { key: 'actions', dataKey: 'actions', title: '操作', width: 80, slots: { default: 'cell-actions' } }] as any, proxyConfig: { autoLoad: false, ajax: { query: async ({ page }) => listApplicationsApi({ mode: auditTab.value, page: page.currentPage, pageSize: page.pageSize }) } }, pagerConfig: { enabled: true, pageSize: 20, pageSizes: [10, 20, 50, 100] }, toolbarConfig: { custom: true, refresh: true, zoom: true } } });
async function loadSection() { await loadBase(); if (section.value === 'dashboard') summary.value = await getSummaryApi({ project_id: filters.value.project_id, responsibility_id: filters.value.responsibility_id }); if (section.value === 'findings') findingGridApi.reload(); if (section.value === 'audit') applicationGridApi.reload(); }
function openCreate(type: typeof dialog.value) { editingId.value = ''; dialog.value = type; if (type === 'project') projectForm.value = { name: '', code: '', repository: '', branch: 'master', description: '', is_active: true }; if (type === 'responsibility') responsibilityForm.value = { name: '', code: '', owner_id: '', approver_ids: [], description: '', is_active: true }; if (type === 'link') linkForm.value = { project_id: '', responsibility_id: '', remark: '', is_active: true }; }
function editProject(row: GovernanceProject) { editingId.value = row.id; projectForm.value = { ...row }; dialog.value = 'project'; }
function editResponsibility(row: GovernanceResponsibility) { editingId.value = row.id; responsibilityForm.value = { name: row.name, code: row.code, owner_id: row.owner?.id || '', approver_ids: row.approvers.map((item) => item.id), description: row.description, is_active: row.is_active }; dialog.value = 'responsibility'; }
async function saveDialog() { try { if (dialog.value === 'project') editingId.value ? await updateProjectApi(editingId.value, projectForm.value) : await createProjectApi(projectForm.value); if (dialog.value === 'responsibility') editingId.value ? await updateResponsibilityApi(editingId.value, responsibilityForm.value) : await createResponsibilityApi(responsibilityForm.value); if (dialog.value === 'link') await createLinkApi(linkForm.value); dialog.value = ''; await loadSection(); ElMessage.success('保存成功'); } catch { /* request interceptor displays the error */ } }
async function remove(type: 'project' | 'responsibility' | 'link', id: string) { await ElMessageBox.confirm('删除后将停止新的数据接入，历史报告仍会保留，确认继续？', '确认删除', { type: 'warning' }); if (type === 'project') await deleteProjectApi(id); if (type === 'responsibility') await deleteResponsibilityApi(id); if (type === 'link') await deleteLinkApi(id); await loadSection(); }
function beforeUpload(rawFile: File) { file.value = rawFile; return false; }
async function submitUpload() { if (!file.value) return ElMessage.warning('请选择 JSON 文件'); const data = new FormData(); data.append('file', file.value); data.append('project_id', uploadForm.value.project_id); data.append('responsibility_id', uploadForm.value.responsibility_id); data.append('tool_name', uploadForm.value.tool_name); await uploadReportApi(data); dialog.value = ''; file.value = null; await loadSection(); ElMessage.success('扫描报告解析完成'); }
function handleSelection(rows: Finding[]) { selected.value = rows; }
function openApply() { if (!selected.value.length) return ElMessage.warning('请选择问题'); const scope = selected.value[0]; if (!scope) return; const item = responsibilities.value.find((row) => row.name === scope.responsibility_name); applyForm.value = { approver_id: item?.approvers[0]?.id || '', reason: '' }; dialog.value = 'apply'; }
async function submitApply() { await createApplicationApi({ finding_ids: selected.value.map((row) => row.id), approver_id: applyForm.value.approver_id, reason: applyForm.value.reason }); dialog.value = ''; selected.value = []; await loadSection(); ElMessage.success('屏蔽申请已提交'); }
async function showFinding(row: Finding) { detail.value = await getFindingApi(row.id); dialog.value = 'detail'; }
function showAudit(row: Application) { auditRow.value = row; auditComment.value = ''; dialog.value = 'audit'; }
async function submitAudit(status: 'approve' | 'reject') { if (!auditRow.value) return; status === 'approve' ? await approveApplicationApi(auditRow.value.id, auditComment.value) : await rejectApplicationApi(auditRow.value.id, auditComment.value); dialog.value = ''; await loadSection(); ElMessage.success('审批已处理'); }
onMounted(loadSection);
</script>

<template>
  <Page :title="pageTitle" auto-content-height>
    <AgentToolsPageShell class="governance-shell">
      <aside class="governance-nav">
        <div class="nav-heading">
          <strong>代码问题治理</strong>
          <span>扫描结果与屏蔽审核</span>
        </div>
        <nav class="nav-list" aria-label="代码问题治理功能">
          <button v-for="item in [{ key: 'dashboard', label: '治理看板' }, { key: 'config', label: '项目与责任田' }, { key: 'findings', label: '问题明细' }, { key: 'audit', label: '屏蔽审核' }]" :key="item.key" :class="['nav-item', { active: section === item.key }]" @click="section = item.key as Section; loadSection()">{{ item.label }}</button>
        </nav>
      </aside>
      <main class="governance-content">
        <template v-if="section === 'dashboard'">
          <div class="toolbar toolbar--dashboard"><div class="toolbar-title">问题概览</div><ElSelect v-model="filters.project_id" clearable placeholder="项目" @change="loadSection"><ElOption v-for="item in projects" :key="item.id" :label="item.name" :value="item.id" /></ElSelect><ElSelect v-model="filters.responsibility_id" clearable placeholder="责任田" @change="loadSection"><ElOption v-for="item in responsibilities" :key="item.id" :label="item.name" :value="item.id" /></ElSelect><ElButton @click="loadSection">刷新</ElButton></div>
          <div class="stat-grid"><ElCard class="metric-card"><ElStatistic title="问题总数" :value="summary.total" /></ElCard><ElCard class="metric-card"><ElStatistic title="待治理" :value="summary.normal" /></ElCard><ElCard class="metric-card"><ElStatistic title="待审批" :value="summary.pending_applications" /></ElCard><ElCard class="metric-card"><ElStatistic title="已屏蔽" :value="summary.shielded" /></ElCard></div>
          <div class="dashboard-grid"><ElCard class="panel-card" header="严重级别"><div v-for="key in ['blocker', 'critical', 'major', 'minor', 'info']" :key="key" class="metric-row"><span>{{ key }}</span><strong>{{ summary.severity?.[key] || 0 }}</strong></div></ElCard><ElCard class="panel-card" header="项目问题排行"><div v-for="row in summary.project_rank || []" :key="row.name" class="metric-row"><span>{{ row.name }}</span><strong>{{ row.count }}</strong></div><ElEmpty v-if="!summary.project_rank?.length" description="暂无数据" :image-size="48" /></ElCard><ElCard class="panel-card" header="责任田问题排行"><div v-for="row in summary.responsibility_rank || []" :key="row.name" class="metric-row"><span>{{ row.name }}</span><strong>{{ row.count }}</strong></div><ElEmpty v-if="!summary.responsibility_rank?.length" description="暂无数据" :image-size="48" /></ElCard></div>
          <ElCard class="panel-card" header="最近扫描"><div v-if="summary.latest_report" class="latest-report"><ElTag :type="summary.latest_report.complete ? 'success' : 'warning'">{{ summary.latest_report.complete ? '扫描完成' : '扫描未完成' }}</ElTag><span>{{ summary.latest_report.project_name }} / {{ summary.latest_report.responsibility_name }}</span><span>{{ summary.latest_report.tool_name }}</span><span>{{ summary.latest_report.finding_count }} 个问题</span></div><ElEmpty v-else description="暂无扫描报告" :image-size="64" /></ElCard>
        </template>
        <template v-else-if="section === 'config'">
          <ElTabs v-model="configTab"><ElTabPane label="项目" name="projects" /><ElTabPane label="责任田" name="responsibilities" /><ElTabPane label="项目×责任田" name="links" /><ElTabPane label="接入扫描" name="upload" /></ElTabs>
          <div class="toolbar"><ElButton v-if="configTab === 'projects'" type="primary" @click="openCreate('project')">新建项目</ElButton><ElButton v-if="configTab === 'responsibilities'" type="primary" @click="openCreate('responsibility')">新建责任田</ElButton><ElButton v-if="configTab === 'links'" type="primary" @click="openCreate('link')">新增关联</ElButton><ElButton v-if="configTab === 'upload'" type="primary" @click="dialog = 'upload'">上传 JSON 报告</ElButton></div>
          <ElTable v-if="configTab === 'projects'" :data="projects" stripe><ElTableColumn prop="name" label="项目名称" /><ElTableColumn prop="code" label="编码" /><ElTableColumn prop="repository" label="仓库" /><ElTableColumn prop="branch" label="分支" /><ElTableColumn label="操作"><template #default="{ row }"><ElButton link type="primary" @click="editProject(row)">编辑</ElButton><ElButton link type="danger" @click="remove('project', row.id)">删除</ElButton></template></ElTableColumn></ElTable>
          <ElTable v-else-if="configTab === 'responsibilities'" :data="responsibilities" stripe><ElTableColumn prop="name" label="责任田" /><ElTableColumn prop="code" label="编码" /><ElTableColumn label="负责人"><template #default="{ row }">{{ row.owner?.name || '-' }}</template></ElTableColumn><ElTableColumn label="审批人"><template #default="{ row }">{{ formatApprovers(row.approvers) }}</template></ElTableColumn><ElTableColumn label="操作"><template #default="{ row }"><ElButton link type="primary" @click="editResponsibility(row)">编辑</ElButton><ElButton link type="danger" @click="remove('responsibility', row.id)">删除</ElButton></template></ElTableColumn></ElTable>
          <ElTable v-else-if="configTab === 'links'" :data="links" stripe><ElTableColumn prop="project_name" label="项目" /><ElTableColumn prop="responsibility_name" label="责任田" /><ElTableColumn prop="remark" label="备注" /><ElTableColumn label="操作"><template #default="{ row }"><ElButton link type="danger" @click="remove('link', row.id)">删除</ElButton></template></ElTableColumn></ElTable>
          <ElEmpty v-else description="点击上方按钮上传第三方 JSON 扫描报告" />
        </template>
        <template v-else-if="section === 'findings'"><div class="toolbar"><div class="toolbar-title">问题明细</div><ElSelect v-model="filters.severity" clearable placeholder="严重级别" @change="findingGridApi.reload()"><ElOption v-for="key in ['blocker', 'critical', 'major', 'minor', 'info']" :key="key" :label="key" :value="key" /></ElSelect><ElSelect v-model="filters.shield_status" clearable placeholder="屏蔽状态" @change="findingGridApi.reload()"><ElOption label="正常" value="Normal" /><ElOption label="申请中" value="Pending" /><ElOption label="已屏蔽" value="Shielded" /><ElOption label="已驳回" value="Rejected" /></ElSelect><ElInput v-model="filters.keyword" placeholder="搜索文件、规则、问题描述" clearable @keyup.enter="findingGridApi.reload()" /><ElButton type="primary" @click="openApply">申请屏蔽</ElButton></div><FindingGrid @selection-change="handleSelection"><template #cell-severity="{ row }"><ElTag :type="row.severity === 'blocker' || row.severity === 'critical' ? 'danger' : 'warning'">{{ row.severity }}</ElTag></template><template #cell-actions="{ row }"><ElButton link type="primary" @click="showFinding(row)">详情</ElButton></template></FindingGrid></template>
        <template v-else><ElTabs v-model="auditTab" @tab-change="loadSection"><ElTabPane label="待我审批" name="my_audit" /><ElTabPane label="我的申请" name="my_apply" /></ElTabs><ApplicationGrid><template #cell-actions="{ row }"><ElButton v-if="auditTab === 'my_audit' && row.status === 'Pending'" link type="primary" @click="showAudit(row)">审批</ElButton></template></ApplicationGrid></template>
      </main>
    </AgentToolsPageShell>
    <ElDialog v-model="dialogVisible" title="项目" width="560px"><ElForm v-if="dialog === 'project'" :model="projectForm" label-width="90px"><ElFormItem label="项目名称"><ElInput v-model="projectForm.name" /></ElFormItem><ElFormItem label="项目编码"><ElInput v-model="projectForm.code" /></ElFormItem><ElFormItem label="仓库地址"><ElInput v-model="projectForm.repository" /></ElFormItem><ElFormItem label="默认分支"><ElInput v-model="projectForm.branch" /></ElFormItem><ElFormItem label="描述"><ElInput v-model="projectForm.description" type="textarea" /></ElFormItem></ElForm><ElForm v-else-if="dialog === 'responsibility'" :model="responsibilityForm" label-width="90px"><ElFormItem label="责任田名称"><ElInput v-model="responsibilityForm.name" /></ElFormItem><ElFormItem label="责任田编码"><ElInput v-model="responsibilityForm.code" /></ElFormItem><ElFormItem label="负责人"><ElSelect v-model="responsibilityForm.owner_id" clearable><ElOption v-for="item in users" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="审批人员"><ElSelect v-model="responsibilityForm.approver_ids" multiple><ElOption v-for="item in users" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="描述"><ElInput v-model="responsibilityForm.description" type="textarea" /></ElFormItem></ElForm><ElForm v-else-if="dialog === 'link'" :model="linkForm" label-width="90px"><ElFormItem label="项目"><ElSelect v-model="linkForm.project_id"><ElOption v-for="item in projects" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="责任田"><ElSelect v-model="linkForm.responsibility_id"><ElOption v-for="item in responsibilities" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="备注"><ElInput v-model="linkForm.remark" /></ElFormItem></ElForm><ElForm v-else-if="dialog === 'upload'" :model="uploadForm" label-width="90px"><ElFormItem label="项目"><ElSelect v-model="uploadForm.project_id"><ElOption v-for="item in projects" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="责任田"><ElSelect v-model="uploadForm.responsibility_id"><ElOption v-for="item in responsibilities" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="扫描工具"><ElInput v-model="uploadForm.tool_name" /></ElFormItem><ElUpload accept=".json,application/json" :before-upload="beforeUpload" :auto-upload="false"><ElButton>选择 JSON</ElButton></ElUpload></ElForm><ElForm v-else-if="dialog === 'apply'" :model="applyForm" label-width="90px"><ElFormItem label="审批人"><ElSelect v-model="applyForm.approver_id"><ElOption v-for="item in applyApprovers" :key="item.id" :label="item.name" :value="item.id" /></ElSelect></ElFormItem><ElFormItem label="申请理由"><ElInput v-model="applyForm.reason" type="textarea" /></ElFormItem></ElForm><ElForm v-else-if="dialog === 'audit'" label-width="90px"><ElFormItem label="申请理由">{{ auditRow?.reason }}</ElFormItem><ElFormItem label="审批意见"><ElInput v-model="auditComment" type="textarea" /></ElFormItem></ElForm><div v-else-if="dialog === 'detail' && detail" class="detail-content"><ElDescriptions :column="1" border><ElDescriptionsItem label="稳定身份">{{ detail.identity_key }}</ElDescriptionsItem><ElDescriptionsItem label="Issue Key">{{ detail.issue_key || '-' }}</ElDescriptionsItem><ElDescriptionsItem label="文件">{{ detail.file_path }}</ElDescriptionsItem><ElDescriptionsItem label="问题描述">{{ detail.message }}</ElDescriptionsItem><ElDescriptionsItem label="Identity"><pre>{{ JSON.stringify(detail.identity, null, 2) }}</pre></ElDescriptionsItem><ElDescriptionsItem label="Evidence"><pre>{{ JSON.stringify(detail.evidence, null, 2) }}</pre></ElDescriptionsItem></ElDescriptions></div><template #footer><ElButton @click="dialog = ''">取消</ElButton><ElButton v-if="dialog === 'upload'" type="primary" @click="submitUpload">上传</ElButton><ElButton v-else-if="dialog === 'apply'" type="primary" @click="submitApply">提交申请</ElButton><template v-else-if="dialog === 'audit'"><ElButton type="danger" @click="submitAudit('reject')">驳回</ElButton><ElButton type="primary" @click="submitAudit('approve')">通过</ElButton></template><ElButton v-else-if="['project', 'responsibility', 'link'].includes(dialog)" type="primary" @click="saveDialog">保存</ElButton></template></ElDialog>
  </Page>
</template>

<style scoped>
.governance-shell.agent-tools-page-shell { display: flex; flex-direction: row; height: 100%; min-height: 0; gap: 16px; }
.governance-nav { width: 196px; flex: 0 0 196px; padding: 4px 0; border-right: 1px solid var(--el-border-color-lighter); }
.nav-heading { display: flex; flex-direction: column; gap: 4px; padding: 8px 12px 18px; color: var(--el-text-color-primary); }
.nav-heading strong { font-size: 15px; font-weight: 600; }
.nav-heading span { color: var(--el-text-color-secondary); font-size: 12px; }
.nav-list { display: flex; flex-direction: column; gap: 4px; }
.nav-item { display: block; width: 100%; padding: 9px 12px; border: 1px solid transparent; border-radius: 6px; color: var(--el-text-color-regular); background: transparent; font-size: 13px; text-align: left; cursor: pointer; transition: color .15s, background-color .15s, border-color .15s; }
.nav-item.active { border-color: var(--el-color-primary-light-7); color: var(--el-color-primary); background: var(--el-color-primary-light-9); font-weight: 500; }
.nav-item:hover:not(.active) { color: var(--el-color-primary); background: var(--el-fill-color-light); }
.governance-content { min-width: 0; flex: 1; overflow: auto; padding: 4px 0; }
.toolbar { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }
.toolbar--dashboard { padding-bottom: 2px; }
.toolbar-title { flex: 1; color: var(--el-text-color-primary); font-size: 15px; font-weight: 600; }
.toolbar .el-select { width: 180px; }.toolbar .el-input { width: 280px; }
.stat-grid, .dashboard-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 12px; }.dashboard-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.metric-card, .panel-card { border-color: var(--el-border-color-lighter); box-shadow: none; }
.metric-card :deep(.el-card__body) { padding: 16px 18px; }
.metric-row, .latest-report { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--el-border-color-extra-light); color: var(--el-text-color-regular); font-size: 13px; }.metric-row:last-child { border-bottom: 0; }.metric-row strong { color: var(--el-text-color-primary); font-weight: 600; }.latest-report { justify-content: flex-start; align-items: center; border-bottom: 0; }
.panel-card :deep(.el-card__header) { padding: 12px 16px; color: var(--el-text-color-primary); font-size: 13px; font-weight: 600; }.panel-card :deep(.el-card__body) { padding: 8px 16px 14px; }
.governance-content :deep(.el-tabs__header) { margin-bottom: 14px; }.governance-content :deep(.el-table) { --el-table-header-bg-color: var(--el-fill-color-light); }.governance-content :deep(.el-dialog__body) { padding-top: 10px; }
.detail-content pre { max-height: 220px; overflow: auto; white-space: pre-wrap; }
@media (max-width: 900px) { .governance-nav { width: 166px; flex-basis: 166px; }.stat-grid, .dashboard-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { .governance-shell { gap: 10px; }.governance-nav { width: 132px; flex-basis: 132px; }.nav-heading { padding-left: 8px; }.nav-item { padding-left: 8px; }.stat-grid, .dashboard-grid { grid-template-columns: 1fr; }.toolbar .el-select, .toolbar .el-input { width: 100%; } }
</style>
